import com.pousada.marealta.persistence.RoomDao;
import io.javalin.http.Context;

import java.util.List;

public class RoomHandler {
    private final RoomDao roomDao;

    public RoomHandler(RoomDao roomDao) {
        this.roomDao = roomDao;
    }

    public void listRooms(Context ctx) {
        try {
            List<Room> rooms = roomDao.findAll();
            ctx.json(rooms.stream().map(room -> new Object() {
                public int number = room.getNumber();
                public String type = room.getType().name();
                public int capacity = room.getCapacity();
                public Object nightlyRate = room.getNightlyRate();
            }).toList());
        } catch (Exception e) {
            ErrorHandler.handleException(ctx, e);
        }
    }
}

