            } else if ("OPERATION_NOT_ALLOWED".equals(e.getMessage())) {
                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status");
            } else {
                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
            }
        } catch (Exception e) {
            ErrorHandler.handleException(ctx, e);
        }
    }

    public void getReceipt(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = reservationService.getReservation(id);

            if (reservation.getStatus() == com.pousada.marealta.model.ReservationStatus.PENDING) {
                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Receipt is not available for pending reservations");
                return;
            }

            RoomDao roomDao = (RoomDao) ctx.attribute("roomDao");
            String roomType = roomDao.findByNumber(reservation.getRoomNumber()).getType().name();

            ReceiptDto receipt = new ReceiptDto(
                reservation.getId(),
                reservation.getGuestName(),
                reservation.getGuestCpf(),
                reservation.getRoomNumber(),
                roomType,
                reservation.getCheckIn(),
                reservation.getCheckOut(),
                reservation.getNights(),
                reservation.getSubtotal(),
                reservation.getDiscount(),
                reservation.getTotal()
            );

            ctx.json(receipt);
        } catch (IllegalArgumentException e) {
            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
            } else {
                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
            }
        } catch (Exception e) {
            ErrorHandler.handleException(ctx, e);
        }
    }

    private Object reservationToJson(Reservation reservation) {
        return new Object() {
            public long id = reservation.getId();
            public int roomNumber = reservation.getRoomNumber();
            public String guestName = reservation.getGuestName();
            public String guestEmail = reservation.getGuestEmail();
            public String guestCpf = reservation.getGuestCpf();
            public Object checkIn = reservation.getCheckIn();
            public Object checkOut = reservation.getCheckOut();
            public int guests = reservation.getGuests();
            public String ratePlan = reservation.getRatePlan().name();
            public int nights = reservation.getNights();
            public Object subtotal = reservation.getSubtotal();
            public Object discount = reservation.getDiscount();
            public Object total = reservation.getTotal();
            public String status = reservation.getStatus().name();
            public Object amountPaid = reservation.getAmountPaid();
            public Object refund = reservation.getRefund();
        };
    }
}

